/* CSS for Rent Receipt */
body {
    font-family: 'Arial', sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f4f4f4;
}

.receipt-container {
    width: 80%;
    max-width: 800px;
    margin: 30px auto;
    background-color: #ffffff;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1);
}

.header {
    text-align: center;
    margin-bottom: 20px;
}

.receipt-title {
    font-size: 28px;
    color: #4CAF50;
    margin: 0;
}

.receipt-subtitle {
    font-size: 16px;
    color: #666;
    margin-top: 5px;
}

.receipt-details {
    margin-top: 20px;
}

.receipt-detail {
    display: flex;
    justify-content: space-between;
    margin: 10px 0;
    font-size: 16px;
}

.receipt-detail b {
    font-weight: bold;
    color: #333;
}

.receipt-detail span {
    color: #555;
}

.footer {
    text-align: center;
    margin-top: 20px;
    font-size: 14px;
    color: #888;
}

.footer p {
    margin: 5px 0;
}

/* Add styles for responsive behavior */
@media (max-width: 768px) {
    .receipt-container {
        width: 90%;
    }

    .receipt-title {
        font-size: 24px;
    }

    .receipt-subtitle {
        font-size: 14px;
    }

    .receipt-detail {
        font-size: 14px;
    }
}
